<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {ArrowUpRight,Check,KeyRound,Mail,RefreshCw,Save,ShieldCheck,SlidersHorizontal} from 'lucide-vue-next'
import {call} from '../../../services/gpt-register/web/src/portal/client'
import {notify,type Row} from '../lib'
const props=defineProps<{enabled:boolean;mode:'pricing'|'resources'}>()
const form=ref<Row|null>(null),saved=ref(''),busy=ref(false),loading=ref(false),error=ref('')
const keys=computed(()=>props.mode==='pricing'?['price_standard','price_oauth']:['max_quantity','registration_concurrency','user_registration_concurrency','max_open_orders','attempt_limit','resource_retry_limit','timeout_minutes','template'])
const payload=()=>Object.fromEntries(keys.value.map(k=>[k,form.value?.[k]]))
const dirty=computed(()=>!!form.value&&JSON.stringify(payload())!==saved.value)
const plans=[{key:'price_standard',title:'标准注册',description:'交付邮箱、密码和 2FA，适合基础账号需求。',icon:Mail,items:['完整注册账号','登录凭据与 2FA','交付后扣除服务费']},{key:'price_oauth',title:'注册 + OAuth',description:'完成注册及 OAuth 授权后，交付完整账号资料。',icon:KeyRound,items:['包含标准注册内容','OAuth 授权资料','授权完成后才扣费']}]
const limits=[{key:'max_quantity',label:'每单账号数量',min:1,max:1000,unit:'个',help:'一笔订单最多提交的账号数。'},{key:'max_open_orders',label:'每用户未完成订单',min:1,max:20,unit:'笔',help:'达到上限后，需等待已有订单结算。'},{key:'registration_concurrency',label:'全平台同时注册',min:1,max:100,unit:'个',help:'所有用户共用的执行上限。'},{key:'user_registration_concurrency',label:'单用户同时注册',min:1,max:100,unit:'个',help:'该用户全部注册订单合并计算。'}]
const retries=[{key:'attempt_limit',label:'启动／授权尝试次数',min:1,max:5,unit:'次',help:'包含首次尝试。'},{key:'resource_retry_limit',label:'未交付账号换邮箱次数',min:0,max:10,unit:'次',help:'不含首次使用的邮箱。'},{key:'timeout_minutes',label:'单个账号总时限',min:2,max:120,unit:'分钟',help:'包含换邮箱、恢复及授权等待。'}]
async function load(){if(!props.enabled)return;loading.value=true;error.value='';try{form.value=await call('/api/admin/v1/settings');saved.value=JSON.stringify(payload())}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function save(){if(!form.value||busy.value)return;busy.value=true;error.value='';try{await call('/api/admin/v1/settings','PATCH',payload());saved.value=JSON.stringify(payload());notify(props.mode==='pricing'?'注册价格已保存':'注册资源与调度配置已保存')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function provider(value:string){if(!form.value)return;const template={...form.value.template};if(value)template.mailProvider=value;else delete template.mailProvider;form.value.template=template}
onMounted(load)
</script>
<template>
 <div class="page-heading"><div><span class="eyebrow">OPERATIONS / {{mode==='pricing'?'PRICING':'REGISTRATION RESOURCES'}}</span><h1>{{mode==='pricing'?'服务与定价':'注册资源与调度'}}</h1><p>{{mode==='pricing'?'设置标准账号和 OAuth 账号的服务费。':'管理注册并发、邮箱模板、重试次数和交付时限。'}}</p></div><button class="icon-btn bordered" :disabled="loading||busy||dirty" @click="load" :aria-label="mode==='pricing'?'刷新注册定价':'刷新注册配置'"><RefreshCw :size="18" :class="{spinning:loading}"/></button></div>
 <div v-if="!enabled" class="panel empty"><h2>注册服务尚未连接</h2></div>
 <div v-if="error" class="alert danger" role="alert">{{error}}<button v-if="!form" @click="load">重试</button></div>
 <p v-if="loading&&!form" class="muted" role="status">正在读取注册服务配置…</p>
 <form v-if="form" class="registration-pricing" @submit.prevent="save">
  <fieldset :disabled="busy">
   <div v-if="mode==='pricing'" class="pricing-plans"><section v-for="plan in plans" :key="plan.key" class="panel pricing-plan"><div class="plan-heading"><span class="icon-tile"><component :is="plan.icon" :size="22"/></span><span class="pill">{{plan.key==='price_oauth'?'完整授权':'基础服务'}}</span></div><h2>{{plan.title}}</h2><p class="muted">{{plan.description}}</p><label class="plan-price">标准服务费<div class="price-input"><input v-model.number="form[plan.key]" :aria-label="plan.title+'标准服务费'" type="number" min="0" max="1000000" step="1" required/><span>积分 / 个</span></div></label><ul><li v-for="item in plan.items" :key="item"><Check :size="15"/>{{item}}</li></ul></section></div>
   <div v-if="mode==='pricing'" class="pricing-note"><ShieldCheck :size="20"/><p>下单先冻结积分，成功交付才扣费，未交付部分释放。会员减免与账户专属价在标准价上计算，客户下单时会看到实际单价。</p><a href="#/admin/membership">会员权益<ArrowUpRight :size="14"/></a></div>
   <template v-else><div class="pricing-detail-grid"><section class="panel pricing-section"><div class="section-heading"><div><span class="eyebrow">CAPACITY</span><h2>接单与并发</h2></div><SlidersHorizontal :size="21"/></div><p class="muted section-intro">超出并发的账号进入队列，空出名额后自动继续。调低上限不会中断正在执行的账号。</p><div class="form-grid"><label v-for="f in limits" :key="f.key">{{f.label}}<div class="unit-input"><input v-model.number="form[f.key]" type="number" :min="f.min" :max="f.max" step="1" required/><span>{{f.unit}}</span></div><small>{{f.help}}</small></label></div></section>
   <section class="panel pricing-section"><span class="eyebrow">DELIVERY</span><h2>注册模板</h2><p class="muted section-intro">为后续新订单选择邮箱来源，已受理订单保留原模板。</p><label>邮箱供应商<select :value="form.template?.mailProvider||''" @change="provider(($event.target as HTMLSelectElement).value)"><option value="">使用注册引擎默认设置</option><option value="smsbower">SMSBower Gmail</option><option value="xiaopingguo">小苹果</option><option value="mailcom">Mail.com</option><option value="fastmail">Fastmail</option><option value="icloud">iCloud</option></select></label><div class="template-detail"><b>注册地区由客户选择</b><p>新订单使用已配置的注册代理模式和开放地区，切换设置仅影响后续新订单。</p></div><a class="text-btn" href="/registration/admin/engine/proxies" target="_blank" rel="noopener noreferrer">管理注册资源<ArrowUpRight :size="14"/></a></section></div>
   <section class="panel pricing-section"><span class="eyebrow">RETRY & TIMEOUT</span><h2>重试与交付时限</h2><div class="retry-grid"><label v-for="f in retries" :key="f.key">{{f.label}}<div class="unit-input"><input v-model.number="form[f.key]" type="number" :min="f.min" :max="f.max" step="1" required/><span>{{f.unit}}</span></div><small>{{f.help}}</small></label></div></section></template>
  </fieldset>
  <div class="pricing-save"><p>{{dirty?'有未保存的修改':'配置已同步'}}<small>{{mode==='pricing'?'改价只影响新订单，历史订单保留下单时的价格。':'修改后按现有队列规则生效，执行中的账号不会因调低并发而中断。'}}</small></p><button class="btn primary" :disabled="busy||!dirty"><Save :size="17"/>{{busy?'保存中…':mode==='pricing'?'保存注册价格':'保存注册配置'}}</button></div>
 </form>
</template>
<style scoped>
.pricing-section>.text-btn{display:inline-flex;align-items:center;gap:5px}
.registration-pricing fieldset{border:0;padding:0;margin:0;min-width:0}.pricing-plans{display:grid;grid-template-columns:1fr 1fr;gap:20px}.pricing-plan{padding:26px}.plan-heading{display:flex;justify-content:space-between;align-items:center}.pricing-plan h2{margin:20px 0 8px;font-size:22px}.pricing-plan p{font-size:13px;line-height:1.7}.plan-price{margin:24px 0 20px}.price-input,.unit-input{display:flex;align-items:center;border:1px solid var(--line);border-radius:9px;background:var(--card,#fff);overflow:hidden}.price-input:focus-within,.unit-input:focus-within{border-color:var(--green)}.price-input input,.unit-input input{min-width:0;border:0!important;box-shadow:none!important;background:transparent}.price-input input{font-size:30px;font-weight:650;height:64px}.price-input span,.unit-input span{white-space:nowrap;color:var(--muted);font-size:12px;padding-right:14px}.pricing-plan ul{list-style:none;margin:0;padding:18px 0 0;border-top:1px solid var(--line);display:grid;gap:10px}.pricing-plan li{display:flex;gap:9px;font-size:12px}.pricing-plan li svg{color:var(--green)}.pricing-note{display:flex;align-items:center;gap:12px;background:#edf5f1;border:1px solid #dce9e2;border-radius:12px;padding:17px 20px;margin:20px 0;color:#356b55}.pricing-note>svg{flex-shrink:0}.pricing-note p{flex:1;font-size:12px;line-height:1.8}.pricing-note a{white-space:nowrap;display:flex;align-items:center;gap:5px;font-size:12px}.pricing-detail-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:20px}.pricing-section{padding:24px;margin-bottom:20px}.pricing-section h2{font-size:18px;margin:8px 0 16px}.pricing-section .section-heading{margin-bottom:0}.section-intro{font-size:12px;line-height:1.8;margin-bottom:22px}.pricing-section small{font-size:11px;font-weight:400;color:var(--muted);line-height:1.7}.pricing-section label{font-size:12px}.template-detail{margin:22px 0;padding:16px;background:var(--bg);border-radius:9px;font-size:12px}.template-detail p{margin-top:8px;color:var(--muted);line-height:1.8}.retry-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.pricing-save{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:20px 24px;background:var(--card,#fff);border:1px solid var(--line);border-radius:12px}.pricing-save p{font-size:13px}.pricing-save small{display:block;font-size:11px;color:var(--muted);margin-top:5px}@media(max-width:1000px){.pricing-detail-grid{grid-template-columns:1fr}.retry-grid{gap:14px}}@media(max-width:700px){.pricing-plans,.retry-grid{grid-template-columns:1fr}.pricing-plan,.pricing-section{padding:20px}.pricing-note{align-items:flex-start;flex-wrap:wrap}.pricing-note a{margin-left:32px}.pricing-note p{min-width:180px}.pricing-save{align-items:stretch;flex-direction:column}.pricing-save button{justify-content:center}.pricing-section .form-grid{grid-template-columns:1fr}}
</style>
